-- @profullstack/affiliates: Supabase migration (prefix aff_)
-- Generated by supabaseMigrationSql('aff_'). Same tables as postgresStore, so both stores can share them.
-- Use with supabaseStore(serviceRoleClient). Idempotent.

CREATE TABLE IF NOT EXISTS public.aff_invites (
  id TEXT PRIMARY KEY,
  code_hash TEXT NOT NULL UNIQUE,
  inviter_id TEXT NOT NULL,
  created_at BIGINT NOT NULL,
  expires_at BIGINT,
  used_by TEXT,
  used_at BIGINT,
  note TEXT NOT NULL DEFAULT '',
  revoked_at BIGINT
);
CREATE INDEX IF NOT EXISTS aff_invites_inviter_idx ON public.aff_invites (inviter_id);
CREATE INDEX IF NOT EXISTS aff_invites_used_by_idx ON public.aff_invites (used_by);
CREATE TABLE IF NOT EXISTS public.aff_quotas (
  user_id TEXT PRIMARY KEY,
  total INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS public.aff_codes (
  user_id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  created_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS public.aff_attributions (
  user_id TEXT PRIMARY KEY,
  affiliate_id TEXT NOT NULL,
  code TEXT NOT NULL,
  at BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS aff_attributions_affiliate_idx ON public.aff_attributions (affiliate_id);

-- RLS on with no policies: anon and authenticated keys see nothing. Access goes only through the
-- SECURITY DEFINER functions below, which only service_role may execute.
ALTER TABLE public.aff_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.aff_quotas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.aff_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.aff_attributions ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.aff_get_quota(p_user TEXT)
RETURNS INTEGER
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT total FROM public.aff_quotas WHERE user_id = p_user
$fn$;

CREATE OR REPLACE FUNCTION public.aff_set_quota(p_user TEXT, p_total INTEGER)
RETURNS VOID
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
INSERT INTO public.aff_quotas (user_id, total) VALUES (p_user, p_total)
  ON CONFLICT (user_id) DO UPDATE SET total = excluded.total
$fn$;

CREATE OR REPLACE FUNCTION public.aff_count_invites(p_inviter TEXT)
RETURNS INTEGER
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT count(*)::INTEGER FROM public.aff_invites WHERE inviter_id = p_inviter AND (revoked_at IS NULL OR used_by IS NOT NULL)
$fn$;

CREATE OR REPLACE FUNCTION public.aff_insert_invite(p_id TEXT, p_hash TEXT, p_inviter TEXT, p_created BIGINT, p_expires BIGINT, p_note TEXT, p_limit INTEGER)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  -- Per-inviter lock; plpgsql takes a fresh snapshot per statement, so the count sees every committed invite.
  PERFORM pg_advisory_xact_lock(hashtext('aff_invites'), hashtext(p_inviter));
  IF (SELECT count(*) FROM public.aff_invites WHERE inviter_id = p_inviter AND (revoked_at IS NULL OR used_by IS NOT NULL)) >= p_limit THEN
    RETURN FALSE;
  END IF;
  INSERT INTO public.aff_invites (id, code_hash, inviter_id, created_at, expires_at, note)
    VALUES (p_id, p_hash, p_inviter, p_created, p_expires, coalesce(p_note, ''));
  RETURN TRUE;
END
$fn$;

CREATE OR REPLACE FUNCTION public.aff_get_invite_by_hash(p_hash TEXT)
RETURNS SETOF public.aff_invites
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT * FROM public.aff_invites WHERE code_hash = p_hash
$fn$;

CREATE OR REPLACE FUNCTION public.aff_get_invite(p_id TEXT)
RETURNS SETOF public.aff_invites
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT * FROM public.aff_invites WHERE id = p_id
$fn$;

CREATE OR REPLACE FUNCTION public.aff_claim_invite(p_id TEXT, p_user TEXT, p_at BIGINT)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
WITH won AS (
  UPDATE public.aff_invites SET used_by = p_user, used_at = p_at
  WHERE id = p_id AND used_by IS NULL AND revoked_at IS NULL
  RETURNING 1
)
SELECT EXISTS (SELECT 1 FROM won)
$fn$;

CREATE OR REPLACE FUNCTION public.aff_revoke_invite(p_id TEXT, p_at BIGINT)
RETURNS VOID
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
UPDATE public.aff_invites SET revoked_at = p_at WHERE id = p_id AND revoked_at IS NULL
$fn$;

CREATE OR REPLACE FUNCTION public.aff_list_invites(p_inviter TEXT)
RETURNS SETOF public.aff_invites
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT * FROM public.aff_invites WHERE inviter_id = p_inviter ORDER BY created_at DESC, id
$fn$;

CREATE OR REPLACE FUNCTION public.aff_invited_by(p_user TEXT)
RETURNS TEXT
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT inviter_id FROM public.aff_invites WHERE used_by = p_user ORDER BY used_at ASC LIMIT 1
$fn$;

CREATE OR REPLACE FUNCTION public.aff_invitees(p_inviter TEXT)
RETURNS TABLE (user_id TEXT, at BIGINT)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT used_by, used_at FROM public.aff_invites
  WHERE inviter_id = p_inviter AND used_by IS NOT NULL ORDER BY used_at ASC
$fn$;

CREATE OR REPLACE FUNCTION public.aff_get_affiliate_code(p_user TEXT)
RETURNS TEXT
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT code FROM public.aff_codes WHERE user_id = p_user
$fn$;

CREATE OR REPLACE FUNCTION public.aff_put_affiliate_code(p_user TEXT, p_code TEXT, p_at BIGINT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
BEGIN
  INSERT INTO public.aff_codes (user_id, code, created_at) VALUES (p_user, p_code, p_at) ON CONFLICT DO NOTHING;
  RETURN (SELECT code FROM public.aff_codes WHERE user_id = p_user);
END
$fn$;

CREATE OR REPLACE FUNCTION public.aff_affiliate_by_code(p_code TEXT)
RETURNS TEXT
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT user_id FROM public.aff_codes WHERE code = p_code
$fn$;

CREATE OR REPLACE FUNCTION public.aff_attribute(p_user TEXT, p_affiliate TEXT, p_code TEXT, p_at BIGINT)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
WITH ins AS (
  INSERT INTO public.aff_attributions (user_id, affiliate_id, code, at) VALUES (p_user, p_affiliate, p_code, p_at)
  ON CONFLICT (user_id) DO NOTHING
  RETURNING 1
)
SELECT EXISTS (SELECT 1 FROM ins)
$fn$;

CREATE OR REPLACE FUNCTION public.aff_get_attribution(p_user TEXT)
RETURNS SETOF public.aff_attributions
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
SELECT * FROM public.aff_attributions WHERE user_id = p_user
$fn$;

CREATE OR REPLACE FUNCTION public.aff_is_external_code(p_code TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $fn$
DECLARE found BOOLEAN := FALSE;
BEGIN
  IF to_regclass('public.referral_codes') IS NULL THEN
    RETURN FALSE;
  END IF;
  EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.referral_codes WHERE code = $1)'
    INTO found USING upper(btrim(p_code));
  RETURN found;
END
$fn$;

